import json
with open('/app/resources/treasury_bulletin_1990_06.json', 'r') as f:
    data = json.load(f)

# Find tables with Polish or German data
def find_currency_tables(obj, path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            if isinstance(v, str) and ('polish' in v.lower() or 'german' in v.lower() or 'zloty' in v.lower()):
                results.append((new_path, v[:200]))
            results.extend(find_currency_tables(v, new_path))
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:5]):
            results.extend(find_currency_tables(item, f'{path}[{i}]'))
    return results

results = find_currency_tables(data)
for r in results[:10]:
    print(r)
